import { Link } from "react-router-dom";
import { NavigationLinkInfo } from "./NavigationLinkInfo";

const NavigationLink = ({ labelText, href, isActive }: NavigationLinkInfo) => {
  return (
    <Link to={href} className={`navigation-link ${isActive ? "active" : ""}`}>
      {labelText}
    </Link>
  );
};
export default NavigationLink;
